def forward(groups):
    date_part = groups[0]
    time_part = groups[1]
    timestamp = int(date_part) * 1000000 + int(time_part)
    return {'stored': [timestamp], 'layout': []}

def inverse(record):
    timestamp = record['stored'][0]
    date_part = f"{timestamp // 1000000:06d}"
    time_part = f"{timestamp % 1000000:06d}"
    return f"{date_part} {time_part}"
